Lemma blk_rdn : forall s lo hi (a : word) (n : nat),
  blk s lo hi -> lo <= u a -> u a + Z.of_nat n <= hi ->
  exists bs, rdn ml_segs (ms_mem s) a n = Some bs /\ length bs = n /\
